// Bounded ParGeo-style logarithmic batch-dynamic point forest; see package README/LICENSE.
const std=@import("std");
const BdkNode=struct{id:usize,left:usize,right:usize,minx:i64,maxx:i64,miny:i64,maxy:i64};
const bdk_none=std.math.maxInt(usize);
fn bdkLess(a:usize,b:usize,axis:usize,x:*const [32]i64,y:*const [32]i64)bool{const av=if(axis==0)x[a] else y[a];const bv=if(axis==0)x[b] else y[b];if(av!=bv)return av<bv;const aw=if(axis==0)y[a] else x[a];const bw=if(axis==0)y[b] else x[b];return if(aw!=bw)aw<bw else a<b;}
fn bdkBuild(ids:*[32]usize,lo:usize,hi:usize,depth:usize,x:*const [32]i64,y:*const [32]i64,nodes:*[32]BdkNode,used:*usize)usize{if(lo>=hi)return bdk_none;const axis=depth%2;var i=lo+1;while(i<hi):(i+=1){const value=ids[i];var j=i;while(j>lo and bdkLess(value,ids[j-1],axis,x,y)):(j-=1){ids[j]=ids[j-1];}ids[j]=value;}const mid=lo+(hi-lo)/2;const at=used.*;used.*+=1;const id=ids[mid];const left=bdkBuild(ids,lo,mid,depth+1,x,y,nodes,used);const right=bdkBuild(ids,mid+1,hi,depth+1,x,y,nodes,used);nodes[at]=.{.id=id,.left=left,.right=right,.minx=x[id],.maxx=x[id],.miny=y[id],.maxy=y[id]};for([_]usize{left,right})|child|{if(child!=bdk_none){nodes[at].minx=@min(nodes[at].minx,nodes[child].minx);nodes[at].maxx=@max(nodes[at].maxx,nodes[child].maxx);nodes[at].miny=@min(nodes[at].miny,nodes[child].miny);nodes[at].maxy=@max(nodes[at].maxy,nodes[child].maxy);}}return at;}
fn bdkBox(n:BdkNode,qx:i64,qy:i64)i64{const dx=if(qx<n.minx)n.minx-qx else if(qx>n.maxx)qx-n.maxx else 0;const dy=if(qy<n.miny)n.miny-qy else if(qy>n.maxy)qy-n.maxy else 0;return dx*dx+dy*dy;}
fn bdkQuery(at:usize,nodes:*const [32]BdkNode,x:*const [32]i64,y:*const [32]i64,active:*const [32]bool,qx:i64,qy:i64,best:*?struct{d:i64,id:usize})void{if(at==bdk_none)return;const n=nodes[at];if(best.*)|b|{if(bdkBox(n,qx,qy)>b.d)return;}const id=n.id;if(active[id]){const dx=x[id]-qx;const dy=y[id]-qy;const candidate=.{.d=dx*dx+dy*dy,.id=id};if(best.*==null or candidate.d<best.*.?.d or (candidate.d==best.*.?.d and id<best.*.?.id))best.*=candidate;}var a=n.left;var b=n.right;if(a!=bdk_none and b!=bdk_none and bdkBox(nodes[b],qx,qy)<bdkBox(nodes[a],qx,qy)){const t=a;a=b;b=t;}bdkQuery(a,nodes,x,y,active,qx,qy,best);bdkQuery(b,nodes,x,y,active,qx,qy,best);}
fn bdkInsert(levels:*[6][32]usize,sizes:*[6]usize,id:usize) void {
    var carry:[32]usize=@splat(0);carry[0]=id;var count:usize=1;
    for(0..6)|level|{if(sizes[level]==0){for(0..count)|i|{levels[level][i]=carry[i];}sizes[level]=count;return;}var next:[32]usize=@splat(0);var next_count:usize=0;for(0..sizes[level])|i|{next[next_count]=levels[level][i];next_count+=1;}for(0..count)|i|{next[next_count]=carry[i];next_count+=1;}sizes[level]=0;for(0..next_count)|i|{carry[i]=next[i];}count=next_count;}
}
pub export fn batch_dynamic_kd_tree(values:?[*]const i64,length:usize,output:?[*]u8,output_capacity:usize)i64{
    const input=values orelse return -1;if(length<2 or length>250)return -1;const initial0=input[0];if(initial0<0 or initial0>8 or length<2+3*@as(usize,@intCast(initial0)))return -1;
    var x:[32]i64=@splat(0);var y:[32]i64=@splat(0);var answers:[8]i64=@splat(0);var ever:[32]bool=@splat(false);var active:[32]bool=@splat(false);var levels:[6][32]usize=@splat(@splat(0));var sizes:[6]usize=@splat(0);var pos:usize=1;var inserted:usize=0;
    for(0..@intCast(initial0)) |_|{const id0=input[pos];const px=input[pos+1];const py=input[pos+2];pos+=3;if(id0<0 or id0>=32 or !(-1000<=px and px<=1000) or !(-1000<=py and py<=1000))return -1;const id:usize=@intCast(id0);if(ever[id])return -1;for(0..32)|j|{if(active[j] and x[j]==px and y[j]==py)return -1;}x[id]=px;y[id]=py;ever[id]=true;active[id]=true;inserted+=1;bdkInsert(&levels,&sizes,id);}
    if(pos>=length)return -1;const batch0=input[pos];pos+=1;if(batch0<1 or batch0>8)return -1;const batches:usize=@intCast(batch0);
    for(0..batches)|batch|{if(pos+2>length)return -1;const kind=input[pos];const count0=input[pos+1];pos+=2;if((kind!=0 and kind!=1) or count0<1 or count0>8)return -1;const count:usize=@intCast(count0);
        if(kind==0){if(inserted+count>32 or pos+3*count+2>length)return -1;const records_start=pos;for(0..count)|j|{const id0=input[pos];const px=input[pos+1];const py=input[pos+2];pos+=3;if(id0<0 or id0>=32 or !(-1000<=px and px<=1000) or !(-1000<=py and py<=1000))return -1;const id:usize=@intCast(id0);if(ever[id])return -1;for(0..32)|t|{if(active[t] and x[t]==px and y[t]==py)return -1;}for(0..j)|t|{if(input[records_start+3*t+1]==px and input[records_start+3*t+2]==py)return -1;}x[id]=px;y[id]=py;ever[id]=true;active[id]=true;inserted+=1;bdkInsert(&levels,&sizes,id);}}
        else{if(pos+count+2>length)return -1;for(0..count)|_|{const id0=input[pos];pos+=1;if(id0<0 or id0>=32)return -1;const id:usize=@intCast(id0);if(!active[id])return -1;active[id]=false;}}
        if(pos+2>length)return -1;const qx=input[pos];const qy=input[pos+1];pos+=2;if(!(-1000<=qx and qx<=1000) or !(-1000<=qy and qy<=1000))return -1;var best:?struct{d:i64,id:usize}=null;for(0..6)|level|{if(sizes[level]>0){var ids:[32]usize=@splat(0);for(0..sizes[level])|j|{ids[j]=levels[level][j];}var nodes:[32]BdkNode=undefined;var used:usize=0;const root=bdkBuild(&ids,0,sizes[level],0,&x,&y,&nodes,&used);bdkQuery(root,&nodes,&x,&y,&active,qx,qy,&best);}}if(best==null)return -1;answers[batch]=best.?.d;
    }
    if(pos!=length)return -1;const needed=8*batches;const out=output orelse return -2;if(output_capacity<needed)return -2;for(0..needed)|i|{const bits:u64=@bitCast(answers[i/8]);out[i]=@truncate(bits>>@intCast(8*(i%8)));}return @intCast(needed);
}
